/* @lc app=leetcode id=3490 lang=kotlin */ class Solution { companion object { val T: List<List<IntArray>> = (1..81).map { s -> (1..9).fold(listOf(IntArray((s + 1) * s).also { it[0] = 1 })) { acc, _ -> acc + listOf(IntArray((s + 1) * s).also { nx -> (0..s).forEach { rem -> (0 until s).forEach { pm -> nx[rem * s + pm] = (0..minOf(9, rem)).sumOf { dg -> acc.last()[(rem - dg) * s + (pm * dg) % s] } } } }) } } } fun cnt(N: Int, s: Int): Int = N.toString().map { it - '0' }.let { dg -> dg.size.let { L -> T[s - 1].let { G -> (1 until L).sumOf { len -> (1..9).sumOf { d -> if (d <= s) G[len - 1][(s - d) * s + d % s] else 0 } } + dg.indices.fold(Triple(0, 1 % s, 0)) { (sp, pp, acc), i -> Triple(sp + dg[i], pp * dg[i] % s, acc + (if (i == 0) 1 else 0).let { st -> (st until dg[i]).sumOf { d -> if (sp + d <= s) G[L - 1 - i][(s - sp - d) * s + pp * d % s] else 0 } }) }.let { (sp, pp, acc) -> acc + (if (sp == s && pp == 0) 1 else 0) } } } } fun beautifulNumbers(l: Int, r: Int): Int = (1..81).sumOf { s -> cnt(r, s) - cnt(l - 1, s) } }